INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(50311, 'Psalms 89:21', 'Psalms', 89, 21, 'زه په خپل لاس به هغه ټینګ ساتم او زما مټ به هم ځواکمن کړي هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_21.mp3', '', 1761754199, 1761754199),
(50312, 'Psalms 89:22', 'Psalms', 89, 22, 'کله به هم دښمنان نه شي بریالي په هغه او بدکاران به ظلم ونه کړي په هغه باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_22.mp3', '', 1761754199, 1761754199),
(50313, 'Psalms 89:23', 'Psalms', 89, 23, 'زه به مات کړم د هغه دښمنان د هغه مخکې هغه به ووژنم چې ده څخه نفرت کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_23.mp3', '', 1761754199, 1761754199),
(50314, 'Psalms 89:24', 'Psalms', 89, 24, 'زما وفا او تلپاتې مینه به وي هغه سره زما د نوم په وسیله به شي سرلوړی هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_24.mp3', '', 1761754199, 1761754199),
(50315, 'Psalms 89:25', 'Psalms', 89, 25, 'په دریاب به واک اختیار د هغه لاس ته ورکړم ښي لاس به کړمه اوږد تر سیندونو پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_25.mp3', '', 1761754199, 1761754199),
(50316, 'Psalms 89:26', 'Psalms', 89, 26, 'هغه به ماته اواز وکړي: ته زما پلار او خدای یې هم مې ساتونکی او ژغورونکی یې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_26.mp3', '', 1761754199, 1761754199),
(50317, 'Psalms 89:27', 'Psalms', 89, 27, 'ورته به ورکړم مرتبه د مشر زوی ټولو شاهانو د نړۍ کې به یې لوړ وي موقف', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_27.mp3', '', 1761754199, 1761754199),
(50318, 'Psalms 89:28', 'Psalms', 89, 28, 'زه تر ابده خپله مینه به ساتم ورسره او زما لوظ به وي تل ټینګ ورسره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_28.mp3', '', 1761754199, 1761754199),
(50319, 'Psalms 89:29', 'Psalms', 89, 29, 'اولاده به یې شاهان کړم تل ترتله ترڅو چې پاتې اسمانونه وي ساتم به یې تخت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_29.mp3', '', 1761754199, 1761754199),
(50320, 'Psalms 89:30', 'Psalms', 89, 30, 'سرغړونه که یې وکړي اولاده زما له قانونه څخه او چلند زما د حکمونو سره سم ونه کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_30.mp3', '', 1761754199, 1761754199),
(50321, 'Psalms 89:31', 'Psalms', 89, 31, 'که چېرې دوی زما قانون مات کړي او عمل ونه کړي په حکمونو زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_31.mp3', '', 1761754199, 1761754199),
(50322, 'Psalms 89:32', 'Psalms', 89, 32, 'نو دوی ته به ورکړم په کوتک د ګناهونو سزا او د بدیو سزا به ورکړم په قمچینه باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_32.mp3', '', 1761754199, 1761754199),
(50323, 'Psalms 89:33', 'Psalms', 89, 33, 'خو لاس به وانخلمه د خپلې دوامدارې مینې زه له داوده څخه او نه به کله ورسره بې‌وفایي وکړمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_33.mp3', '', 1761754199, 1761754199),
(50324, 'Psalms 89:34', 'Psalms', 89, 34, 'خپل لوظ به مات نه کړمه زه له هغه سره او خپلې خبرې نه به کله هم وانه وړمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_34.mp3', '', 1761754199, 1761754199),
(50325, 'Psalms 89:35', 'Psalms', 89, 35, 'یوځل خوړلی مې قسم په خپل سپېڅلي نوم زه به داود ته هېڅ وخت دروغ نه وایم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_35.mp3', '', 1761754199, 1761754199),
(50326, 'Psalms 89:36', 'Psalms', 89, 36, 'وي به موجوده اولاده د هغه تل دپاره او پاچاهي به یې تل موجوده وي د لمر په شان زما په وړاندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_36.mp3', '', 1761754199, 1761754199),
(50327, 'Psalms 89:37', 'Psalms', 89, 37, 'دا به سپوږمۍ په شان تلپاتې وي چې ده اسمان کې وفاداره ګواه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_37.mp3', '', 1761754199, 1761754199),
(50328, 'Psalms 89:38', 'Psalms', 89, 38, 'خو ای څښتنه، ډېر په قهر یې هغه پاچا ته چې دې په خپله غوره کړی ؤ او اوس پریښی او رد کړی دی تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_38.mp3', '', 1761754199, 1761754199),
(50329, 'Psalms 89:39', 'Psalms', 89, 39, 'تا خپل خادم سره خپل لوظ مات کړی او غورځولی تا یې تاج په ځمکه او هم بې‌حرمته کړی دی تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_39.mp3', '', 1761754199, 1761754199),
(50330, 'Psalms 89:40', 'Psalms', 89, 40, 'ټول دېوالونه دې د ښار رانړولي ورته دي کلا‌ګانې اړولې کنډوالو باندې دې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_40.mp3', '', 1761754199, 1761754199),
(50331, 'Psalms 89:41', 'Psalms', 89, 41, 'ټول مال او جایداد یې لارویانو تالا کړی دی ورپورې ټولو ګاونډیانو یې خندا کړې ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_41.mp3', '', 1761754199, 1761754199),
(50332, 'Psalms 89:42', 'Psalms', 89, 42, 'تا ورکړی دی بری دښمنانو د هغه ته هغوی ټول دې په هغه دي خوشحال کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_42.mp3', '', 1761754199, 1761754199),
(50333, 'Psalms 89:43', 'Psalms', 89, 43, 'تا پڅه کړې د هغه توره ده نه دې جګړه کې ده ورکړې مرسته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_43.mp3', '', 1761754199, 1761754199),
(50334, 'Psalms 89:44', 'Psalms', 89, 44, 'له منځه وړی دې دی د هغه شان او شوکت او راویشتلی دې دی د هغه تخت په ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_44.mp3', '', 1761754199, 1761754199),
(50335, 'Psalms 89:45', 'Psalms', 89, 45, 'خپل وخت نه مخکې دې زوړ کړی هغه او په شرمونو دې پټ کړی هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_45.mp3', '', 1761754199, 1761754199),
(50336, 'Psalms 89:46', 'Psalms', 89, 46, 'ته به ترڅو پورې خپل ځان پټوې ای څښتنه؟ ته تر ابده به خپل ځان پټوې؟ لکه د اور په شان بلیږي به ترڅو ستا قهر؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_46.mp3', '', 1761754199, 1761754199),
(50337, 'Psalms 89:47', 'Psalms', 89, 47, 'ته در په یاد کړه زما عمر چې دی څومره لنډ دا هم په یاد کړه چې مونږ ټول دې بې‌مقصده یو خلق کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_47.mp3', '', 1761754199, 1761754199),
(50338, 'Psalms 89:48', 'Psalms', 89, 48, 'څوک شي کولای چې ژوندی وي تل او هېڅ مړ نه شي؟ څوک شي کولای چې ځان بچ کړي له منګولو د ګور؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_48.mp3', '', 1761754199, 1761754199),
(50339, 'Psalms 89:49', 'Psalms', 89, 49, 'څه شوه څښتنه، ستا تلپاتې پخوانۍ مینه؟ هغه قسم څه شو چې تا کړی ؤ وفادارۍ کې د داود سره تا؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_49.mp3', '', 1761754199, 1761754199),
(50340, 'Psalms 89:50', 'Psalms', 89, 50, 'څومره ملنډې وهي خلک ګوره ستا په خادم دا چې زه څنګه سپکاوی د نورو قومونو زغمم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_50.mp3', '', 1761754199, 1761754199),
(50341, 'Psalms 89:51', 'Psalms', 89, 51, 'ای څښتنه، ستا دښمنان وهي ملنډې په هغه پاچا چې غوره کړی دی تا چېرته چې ځي وهي ملنډې پرې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_51.mp3', '', 1761754199, 1761754199),
(50342, 'Psalms 89:52', 'Psalms', 89, 52, 'ثنا صفت دې وي څښتن ته تر ابده پورې! امین! امین!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms89_verse_52.mp3', '', 1761754199, 1761754199),
(50343, 'Job 11:1', 'Job', 11, 1, 'بيا ضوفر نعماتى جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_1.mp3', '', 1761754199, 1761754199),
(50344, 'Job 11:2', 'Job', 11, 2, '”د ډېرو خبرو جواب په کار نۀ دے څۀ؟ ولې يو سړے په ډېرو خبرو خپل ځان بې‌ګناه ثابتولے شى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_2.mp3', '', 1761754199, 1761754199),
(50345, 'Job 11:3', 'Job', 11, 3, 'ستا فالتو خبرې دې نور خلق غلى کړى څۀ؟ کله چې تۀ د چا سپکاوے کوې، نو څوک به تا ته ګوته نۀ نيسى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_3.mp3', '', 1761754199, 1761754199),
(50346, 'Job 11:4', 'Job', 11, 4, 'ځکه چې تۀ وائې چې زما عقيده ټيک ده، او زۀ د خُدائ پاک په نظر کښې صفا يم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_4.mp3', '', 1761754199, 1761754199),
(50347, 'Job 11:5', 'Job', 11, 5, 'کاش چې خُدائ پاک کلام کړے وے، او هغۀ تا ته صفا وېنا کړے وے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_5.mp3', '', 1761754199, 1761754199),
(50348, 'Job 11:6', 'Job', 11, 6, 'او هغه به تا ته د حِکمت رازُونه وښائى. ځکه چې رښتينے حِکمت په ډېرو طريقو سره حاصليږى. نو بيا پوهه شه چې خُدائ پاک تا له د هغې نه کمه سزا درکوى چې څومره تۀ د ګناه په وجه حقدار يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_6.mp3', '', 1761754199, 1761754199),
(50349, 'Job 11:7', 'Job', 11, 7, 'ولې تۀ د خُدائ پاک هغه پټې خبرې معلومولے شې؟ او يا تۀ د قادر خُدائ حد معلومولے شې څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_7.mp3', '', 1761754199, 1761754199),
(50350, 'Job 11:8', 'Job', 11, 8, 'دا حد د آسمان نه اوچت دے، تۀ څۀ کولے شې؟ او د مرګ د کندې نه ډُوب دے، تا ته څۀ پته ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_8.mp3', '', 1761754199, 1761754199),
(50351, 'Job 11:9', 'Job', 11, 9, 'د دې پېمانه د زمکې نه اوږده ده، او د سمندر نه پلنه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_9.mp3', '', 1761754199, 1761754199),
(50352, 'Job 11:10', 'Job', 11, 10, 'کۀ خُدائ پاک راشى او تا په قېدخانه کښې واچوى، او هغه د اِنصاف دپاره عدالت جوړ کړى، نو هغه څوک ايسارولے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_10.mp3', '', 1761754199, 1761754199),
(50353, 'Job 11:11', 'Job', 11, 11, 'ځکه چې هغۀ ته پته ده چې څوک دوکه باز دے، او هغه يې د هرې ګناه نه خبر وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_11.mp3', '', 1761754199, 1761754199),
(50354, 'Job 11:12', 'Job', 11, 12, 'خو يو کم عقل کس به په هغه وخت هوښيار شى، چې کله د يوې کوچاڼې نه يو انسان پېدا شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_12.mp3', '', 1761754199, 1761754199),
(50355, 'Job 11:13', 'Job', 11, 13, 'کله چې ستا خپل زړۀ تيار شې، او لاسونه هغۀ ته اوچت کړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_13.mp3', '', 1761754199, 1761754199),
(50356, 'Job 11:14', 'Job', 11, 14, 'د ګناهونو نه ځان خلاص کړې، او بدعملى د خپل کور نه ختمه کړې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_14.mp3', '', 1761754199, 1761754199),
(50357, 'Job 11:15', 'Job', 11, 15, 'نو يقيناً به بيا تۀ خپل سر بغېر د څۀ شرم نه اوچت کړې، تۀ به په امن کښې يې او نور به نۀ يرېږې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_15.mp3', '', 1761754199, 1761754199),
(50358, 'Job 11:16', 'Job', 11, 16, 'تۀ به خپل غم هېر کړې، او داسې به دې هېر شى لکه چې بيا به دې هيڅ خيال کښې نۀ راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_16.mp3', '', 1761754199, 1761754199),
(50359, 'Job 11:17', 'Job', 11, 17, 'او ستا ژوند به د غرمې د نمر نه زيات روښانه وى، او تيارۀ به دې هم د سحر د رڼا په شان وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_17.mp3', '', 1761754199, 1761754199),
(50360, 'Job 11:18', 'Job', 11, 18, 'او ستا به اعتماد پېدا شى، ځکه چې اُميد شته، او تۀ به بچ شې او په حِفاظت کښې به آرام کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_18.mp3', '', 1761754199, 1761754199),
(50361, 'Job 11:19', 'Job', 11, 19, 'تۀ به څملې او هيڅ څوک به تا نۀ يروى، ډېر خلق به ستا نه د مدد اُميد ساتى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_19.mp3', '', 1761754199, 1761754199),
(50362, 'Job 11:20', 'Job', 11, 20, 'خو د بد کاره خلقو سترګې به ړندې شى، او هغوئ به د تېښتې ټولې لارې خطا کړى، او هغوئ به صرف د مرګ په انتظار وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job11_verse_20.mp3', '', 1761754199, 1761754199),
(50363, 'Job 26:1', 'Job', 26, 1, 'بيا ايُوب جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_1.mp3', '', 1761754199, 1761754199),
(50364, 'Job 26:2', 'Job', 26, 2, '”تا د هغه چا مدد څنګه وکړو چې هيڅ طاقت يې نۀ وو. تا هغه کس څنګه بچ کړو چې هيڅ زور يې نۀ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_2.mp3', '', 1761754199, 1761754199),
(50365, 'Job 26:3', 'Job', 26, 3, 'تا يو کم عقل کس له څنګه مشوره ورکړه، او نصيحت دې ورته وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_3.mp3', '', 1761754199, 1761754199),
(50366, 'Job 26:4', 'Job', 26, 4, 'ستا څۀ خيال دے چې څوک به ستا خبرې اورى، او تا ته دا خبرې چا ښودلى دى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_4.mp3', '', 1761754199, 1761754199),
(50367, 'Job 26:5', 'Job', 26, 5, '”د زمکې لاندې په اوبو کښې د مړو روحونه لړزيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_5.mp3', '', 1761754199, 1761754199),
(50368, 'Job 26:6', 'Job', 26, 6, 'د مړو دُنيا خُدائ پاک ته ښکاره ده، او د تباهۍ ځائ پټ نۀ دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_6.mp3', '', 1761754199, 1761754199),
(50369, 'Job 26:7', 'Job', 26, 7, 'خُدائ پاک آسمان خور کړے دے، او زمکه يې بغېر د څۀ څيز نه راځوړنده کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_7.mp3', '', 1761754199, 1761754199),
(50370, 'Job 26:8', 'Job', 26, 8, 'هغه اوبۀ په خپله ټينګه وريځ کښې راغونډوى، او وريځ د دروند والى په وجه نۀ شليږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_8.mp3', '', 1761754199, 1761754199),
(50371, 'Job 26:9', 'Job', 26, 9, 'هغه د سپوږمۍ مخ پټوى، او په دې باندې د هغۀ وريځې خوَرې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_9.mp3', '', 1761754199, 1761754199),
(50372, 'Job 26:10', 'Job', 26, 10, 'هغۀ د اوبو دپاسه د آسمان لمن جوړه کړه، هغۀ د رڼا او تيارې په مينځ کښې حد مقرر کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_10.mp3', '', 1761754199, 1761754199),
(50373, 'Job 26:11', 'Job', 26, 11, 'د آسمان بنيادونه ولړزيږى، او دا د هغۀ په رټنه باندې ودرزيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_11.mp3', '', 1761754199, 1761754199),
(50374, 'Job 26:12', 'Job', 26, 12, 'د خپل طاقت په ذريعه هغۀ سمندر قلار کړو، او د خپلې پوهې په ذريعه يې سمندرى بلا تباه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_12.mp3', '', 1761754199, 1761754199),
(50375, 'Job 26:13', 'Job', 26, 13, 'د هغۀ د ساه په ذريعه آسمان ښائسته شو، او د هغۀ لاس تښتېدونکې بلا وشلوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_13.mp3', '', 1761754199, 1761754199),
(50376, 'Job 26:14', 'Job', 26, 14, 'دا د هغۀ د طاقت معمولى کارنامې دى، دا د يو معمولى آواز په شان دے چې مونږ اورېدلے وى. خو داسې څوک شته چې ورته د هغۀ د دروند آواز د زور پته لګى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job26_verse_14.mp3', '', 1761754199, 1761754199),
(50377, 'Isaiah 43:1', 'Isaiah', 43, 1, 'خو اوس ای یعقوبه! هغه څښتن چې پیدا کړي یې یئ ای اسراییلو! هغه څښتن چې دی خالق ستاسو هغه داسې وایي: «وېرېږئ مه، ځکه ژغورلي مې یئ تاسو تاسو په نوم یئ ما راغوښتي او زما یئ تاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_1.mp3', '', 1761754199, 1761754199),
(50378, 'Isaiah 43:2', 'Isaiah', 43, 2, 'چې تېرېږئ کله تاسو له سیندونو، زه به تاسو سره مل یم چې تېرېږئ کله له سیندونو، نو نه به ډوبېږئ تاسو چې تېرېږئ کله د اور له منځه، نو نه به سوځېږئ تاسو زیان به نه رسوي تاسو ته د اور لمبې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_2.mp3', '', 1761754199, 1761754199),
(50379, 'Isaiah 43:3', 'Isaiah', 43, 3, 'ځکه چې ستاسو څښتن خدای یمه زه زه د اسراییلو سپېڅلی خدای یمه ژغورونکی ستاسو قربانوم زه مصر ستاسو ازادۍ دپاره قربانوم ستاسو بدل کې ایتوپیا او سیبا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_3.mp3', '', 1761754199, 1761754199),
(50380, 'Isaiah 43:4', 'Isaiah', 43, 4, 'تاسو ماته ارزښتمن او عزتمن یئ مینه لرمه زه له تاسو سره نو په دې خاطر زه به قربان کړم خلک ستاسو په ځای او ستاسو بدل کې به قربان کړمه قومونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_4.mp3', '', 1761754199, 1761754199),
(50381, 'Isaiah 43:5', 'Isaiah', 43, 5, 'مه وېرېږئ، زه یم تاسو سره مل! راولم به ستاسو خلک له ختیځه او زه به راغونډ کړم له لوېدیځه تاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_5.mp3', '', 1761754199, 1761754199),
(50382, 'Isaiah 43:6', 'Isaiah', 43, 6, 'زه به ووایم شمال ته پرېږده هغوی چې لاړ شي او وبه وایمه جنوب ته هغوی مه ایساروه راولئ زما زامن له لېرې هېوادونو څخه چې په هر ځای کې دي زما لورګانې پرېږدئ چې بېرته راستنې شي خپل وطن ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_6.mp3', '', 1761754199, 1761754199),
(50383, 'Isaiah 43:7', 'Isaiah', 43, 7, 'چې زما په نوم یادیږي هغه ټول کسان چې پیدا کړي ما هغوی دي خپل جلال دپاره او چې مې خلق کړي هغوی»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_7.mp3', '', 1761754199, 1761754199),
(50384, 'Isaiah 43:8', 'Isaiah', 43, 8, 'څښتن وایي: «راولئ هغه خلک چې لري سترګې خو ړانده دي او لري غوږونه خو کاڼه دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_8.mp3', '', 1761754199, 1761754199),
(50385, 'Isaiah 43:9', 'Isaiah', 43, 9, 'راغونډ شوي ټول قومونه او شوې پوښتنه له هغوی نه چا پېشګویي کړې ده د اوسنیو پېښو؟ چا پېشګویي کړې وه د تېرو شویو پېښو؟ هغوی دې راوړي شاهدان او ثابته دې کړي خپله خبره خلک دې واوري او ودې وایي چې هو، سمه ده دا خبره»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_9.mp3', '', 1761754199, 1761754199),
(50386, 'Isaiah 43:10', 'Isaiah', 43, 10, 'څښتن وایي: «ای د اسراییلو قومه تاسو یئ زما شاهدان او غوره کړي مې یئ د خدمتګار په توګه ترڅو ما وپېژنئ او راوړئ ایمان په ما او په دې پوه شئ چې زه یم یوازېنی خدای پرته له ما نشته دی بل خدای هېڅکله نه ؤ او نه به وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_10.mp3', '', 1761754199, 1761754199),
(50387, 'Isaiah 43:11', 'Isaiah', 43, 11, 'زه، یوازې زه څښتن یم پرته له ما نه بل ژغورونکی نشته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_11.mp3', '', 1761754199, 1761754199),
(50388, 'Isaiah 43:12', 'Isaiah', 43, 12, 'زه وم چې پېشګویي مې وکړه چې څه به پېښ شي او راغلم زه ستاسو ژغورنې ته پردی خدای نه ؤ چې تاسو ته وکړي دا کارونه تاسو په خپله شاهدان یئ زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_12.mp3', '', 1761754199, 1761754199),
(50389, 'Isaiah 43:13', 'Isaiah', 43, 13, 'زه یم خدای او تل به پاتی شم خدای هیڅوک نه شي خلاصېدی زما له لاسه ما چې څه کړي دي، هغه څوک بدلولی نه شي»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_13.mp3', '', 1761754199, 1761754199),
(50390, 'Isaiah 43:14', 'Isaiah', 43, 14, 'څښتن، ستاسو ژغورونکی، سپېڅلی خدای د اسراییلو، داسې وایي: «ستاسو ژغورنې په خاطر ما ولېږه لښکر بابل ته ترڅو مجبور کړم ټول بابلیان تېښتې ته هغو کشتۍ ګانو کې چې خوښولې هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_14.mp3', '', 1761754199, 1761754199),
(50391, 'Isaiah 43:15', 'Isaiah', 43, 15, 'زه څښتن یم ستاسو سپېڅلی خدای ای اسراییلو، تاسو پیدا کړي یئ ما او زه پاچا یم ستاسو»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_15.mp3', '', 1761754199, 1761754199),
(50392, 'Isaiah 43:16', 'Isaiah', 43, 16, 'څښتن خلاصه کړله په بحیره کې یوه لاره یوې څنډې ته یې کړلې زورورې اوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_16.mp3', '', 1761754199, 1761754199),
(50393, 'Isaiah 43:17', 'Isaiah', 43, 17, 'د تباهۍ لوري ته یې بوتللې د مصر لویې او قوي لښکرې داسې لښکرې چې لرلې یې جنګي ګاډۍ او اسونه هغوی راوغورځېدل او پورته نه شول بیا هېڅکله او مړه شول د ډېوې په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_17.mp3', '', 1761754199, 1761754199),
(50394, 'Isaiah 43:18', 'Isaiah', 43, 18, 'نو څښتن داسې وایي: «هېرې کړئ تېرې پېښې خپل ژوند مه تېروئ په یادولو د پخوانیو پېښو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_18.mp3', '', 1761754199, 1761754199),
(50395, 'Isaiah 43:19', 'Isaiah', 43, 19, 'ګورئ، همدا اوس چې زه کوم کوم نوی کار هغه به کیږي او لیدلی یې شئ تاسو زه به جوړه کړم په دښته کې یوه لاره او په کې جاري به کړمه زه د اوبو سیندونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_19.mp3', '', 1761754199, 1761754199),
(50396, 'Isaiah 43:20', 'Isaiah', 43, 20, 'زما درناوی به کوي وحشي حیوانات، سورلنډیان او شترمرغ ځکه چې زه روانوم اوبه په دښته کې او سیندونه په صحرا کې چې ورکړم اوبه خپلو غوره شویو خلکو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_20.mp3', '', 1761754199, 1761754199),
(50397, 'Isaiah 43:21', 'Isaiah', 43, 21, 'دا هغه خلک دي چې خلق کړي مې دي د خپل ځان دپاره دوی به کوي په ښکاره ثنا او صفت زما»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_21.mp3', '', 1761754199, 1761754199),
(50398, 'Isaiah 43:22', 'Isaiah', 43, 22, 'څښتن وایي: «ای یعقوبه، تاسو ونه کړله غوښتنه د مرستې ای د اسراییلو قومه! ستړي شوي یئ زما نه تاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_22.mp3', '', 1761754199, 1761754199),
(50399, 'Isaiah 43:23', 'Isaiah', 43, 23, 'تاسو رانه وړې سوځېدونکې نذرانې ماته د خپلو پسونو تاسو ونه کړ درناوی زما د قربانیو په کولو سره ما په تاسو ایښی نه ؤ دا بار چې ماته راوړئ نذرانې ما ستړي نه کړئ تاسو د قیمتي خوشبویۍ په دودولو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_23.mp3', '', 1761754199, 1761754199),
(50400, 'Isaiah 43:24', 'Isaiah', 43, 24, 'زما دپاره مو وانخیستله خوشبویه دالچیني په بیه راضي مو نه کړمه زه د وازګو په وړاندې کولو سره خو تاسو کېښوده په ما باندې د خپلو ګناهونو بار زه تاسو ستړی کړمه په خپلو بدو کړنو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_24.mp3', '', 1761754199, 1761754199),
(50401, 'Isaiah 43:25', 'Isaiah', 43, 25, 'زه هغه خدای یم چې د خپل ځان په خاطر پرده اچوم ستاسو ګناهونو باندې او یاد به نه کړم ګناهونه ستاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_25.mp3', '', 1761754199, 1761754199),
(50402, 'Isaiah 43:26', 'Isaiah', 43, 26, 'تاسو په ما چې لګولي کوم تورونه دي راځئ چې لاړ شو محکمې ته خپله دعوه وړاندې کړئ دا ثابته کړئ چې تاسو یئ په حقه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_26.mp3', '', 1761754199, 1761754199),
(50403, 'Isaiah 43:27', 'Isaiah', 43, 27, 'زما په وړاندې ګناه کړې وه ستاسو لومړني نیکه زما په وړاندې شول یاغي ستاسو مشران', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_27.mp3', '', 1761754199, 1761754199),
(50404, 'Isaiah 43:28', 'Isaiah', 43, 28, 'نو ځکه مې لېرې کړل سپېڅلي کاهنان له خپلو دندو څخه او ما راوستله تباهي په اسراییلو باندې پرې مې ښود چې سپکاوی زما د قوم وشي»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah43_verse_28.mp3', '', 1761754199, 1761754199),
(50405, 'Joshua 22:1', 'Joshua', 22, 1, 'بیا یوشع د روبین، جاد او ختیځې منسي د قبیلو خلک راوغوښتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_1.mp3', '', 1761754199, 1761754199),
(50406, 'Joshua 22:2', 'Joshua', 22, 2, 'یوشع هغوی ته وویل: «تاسو هغه ټول کارونه کړي دي چې د څښتن خدمتګار موسی درته امر کړی ؤ او زما ټولو حکمونو ته مو غاړه ایښې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_2.mp3', '', 1761754199, 1761754199),
(50407, 'Joshua 22:3', 'Joshua', 22, 3, 'که څه هم جنګ زیات اوږد شو، خو تاسو په دې موده کې خپل اسراییلي ورونه پریښي نه دي او کومه وظیفه چې ستاسو څښتن خدای تاسو ته سپارلې وه هغه مو سرته رسولې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_3.mp3', '', 1761754199, 1761754199),
(50408, 'Joshua 22:4', 'Joshua', 22, 4, 'اوس ستاسو څښتن خدای د خپلې وعدې سره سم ستاسو ورونو ته ارامي ورکړې ده. نو بېرته خپلو کورونو یعنې هغې ځمکې ته لاړ شئ چې د اردن د سیند په ختیځ کې ده او د څښتن خدمتګار موسی تاسو ته درکړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_4.mp3', '', 1761754199, 1761754199),
(50409, 'Joshua 22:5', 'Joshua', 22, 5, 'تاسو په غور سره د هغو ټولو شیانو څخه اطاعت کوئ چې موسی تاسو ته امر کړی دی چې د خپل څښتن خدای سره مینه کوئ او د هغه رضا پوره کوئ. د هغه حکمونو ته غاړه ږدئ، هغه ته وفادار اوسئ او د زړه له کومي او په خپل ټول توان سره د هغه خدمت کوئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_5.mp3', '', 1761754199, 1761754199),
(50410, 'Joshua 22:9', 'Joshua', 22, 9, 'نو د روبین او جاد د قبیلو او د ختیځې منسي د قبیلې خلک بېرته خپلو کورونو ته لاړل. هغوی د اسراییلو پاتې خلک په شیلوه کې چې په کنعان کې وه، پرېښودل او خپلې خاورې ته چې د جلعاد خاوره وه، لاړل. دا خاوره هغوی د څښتن د حکم سره سم چې د موسی په وسیله یې کړی ؤ، نیولې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua22_verse_9.mp3', '', 1761754199, 1761754199);